<?php
require_once __DIR__ . '/includes/functions.php';
$id=(int)($_GET['id'] ?? (user()['id'] ?? 0));$stmt=db()->prepare('SELECT id,name,email,role,department,position,avatar,created_at FROM users WHERE id=:id');$stmt->execute([':id'=>$id]);$profile=$stmt->fetch();
if(!$profile){flash('error','Profil anggota tidak ditemukan.');redirect('activities.php');}
$stmt=db()->prepare('SELECT COUNT(*) FROM activities WHERE user_id=:id');$stmt->execute([':id'=>$id]);$activityCount=(int)$stmt->fetchColumn();
$stmt=db()->prepare('SELECT COUNT(*) FROM activity_photos p JOIN activities a ON a.id=p.activity_id WHERE a.user_id=:id');$stmt->execute([':id'=>$id]);$photoCount=(int)$stmt->fetchColumn();
$stmt=db()->prepare('SELECT a.id,a.title,a.activity_date,a.activity_time,a.category,(SELECT p.id FROM activity_photos p WHERE p.activity_id=a.id ORDER BY p.id LIMIT 1) AS cover_photo_id,(SELECT COUNT(*) FROM activity_photos p2 WHERE p2.activity_id=a.id) AS photo_count FROM activities a WHERE a.user_id=:id ORDER BY a.activity_date DESC,a.id DESC LIMIT 8');$stmt->execute([':id'=>$id]);$activities=$stmt->fetchAll();
$isOwn=is_logged_in() && (int)$profile['id']===(int)user()['id'];$page_title='Profil Anggota';$active_page='activities';require __DIR__ . '/partials/header.php';
?>
<div class="section-head page-head"><div><a href="activities.php" class="back-link">← Kembali ke kegiatan</a><h2>Profil Anggota</h2><p>Informasi anggota dan kegiatan yang sudah dibagikan ke workspace instansi. Dokumentasi foto hanya tersedia setelah login.</p></div><?php if($isOwn): ?><a href="profile.php" class="btn btn-primary">Edit profil saya</a><?php endif; ?></div>
<div class="profile-layout"><section class="panel profile-summary"><div class="profile-avatar profile-avatar-photo"><img src="<?= e(avatar_url((int)$profile['id'])) ?>" alt="Foto profil <?= e($profile['name']) ?>"></div><h2><?= e($profile['name']) ?></h2><p><?= e($profile['position']?:'Anggota instansi') ?></p><span class="role-pill <?= e($profile['role']) ?>"><?= e(strtoupper($profile['role'])) ?></span><div class="profile-summary-list"><div><span>Unit / Bagian</span><strong><?= e($profile['department']?:'Belum diisi') ?></strong></div><div><span>Bergabung</span><strong><?= e(format_date_id(substr($profile['created_at'],0,10))) ?></strong></div><div><span>Total kegiatan</span><strong><?= $activityCount ?></strong></div><div><span>Foto dokumentasi</span><strong><?= $photoCount ?></strong></div></div></section>
<section class="panel"><div class="panel-head"><div><h3>Kegiatan anggota</h3><p>Menampilkan hingga 8 kegiatan terbaru dari <?= e($profile['name']) ?>.</p></div></div><div class="member-activity-list"><?php if(!$activities): ?><div class="empty"><strong>Belum ada kegiatan.</strong><span>Kegiatan yang dicatat anggota ini akan tampil di sini.</span></div><?php endif; ?><?php foreach($activities as $a): ?><a class="member-activity-row" href="activity_view.php?id=<?= (int)$a['id'] ?>"><?php if($a['cover_photo_id'] && is_logged_in()): ?><img src="<?= e(photo_url((int)$a['cover_photo_id'])) ?>" alt=""><?php elseif($a['cover_photo_id']): ?><span class="member-activity-placeholder">🔒</span><?php else: ?><span class="member-activity-placeholder">▤</span><?php endif; ?><span class="member-activity-copy"><strong><?= e($a['title']) ?></strong><small><?= e(format_date_id($a['activity_date'])) ?> · <?= e($a['category']) ?></small></span><span class="member-photo-count">📷 <?= (int)$a['photo_count'] ?></span></a><?php endforeach; ?></div></section></div>
<?php require __DIR__ . '/partials/footer.php'; ?>
